                    e[k] = held.get(k, '')
            if e['date_kind'] in ['', 'none']:
                e['date_kind'] = held.get('date_kind', 'none')
            s['held_proposal'] = dict()
        proposal = bool(e['date_text'] or e['amount_text'])
        handled = False
        if kind == 'ai':
            prefix += "I am Freya Bank's digital assistant. "
