        if not handled and s['phase'] == 'name':
            name = norm(e['answer_text'])
            valid_names = [norm(vars.get('first_name', '')), norm(vars.get('last_name', '')), norm(str(vars.get('first_name', '')) + ' ' + str(vars.get('last_name', ''))), norm(str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')))]
            confirmed = kind == 'name_confirmed' and (yes == 'yes' or name in [x for x in valid_names if x] or name in ['speaking', 'that s me'])
            if asks == 0 and e['reply_context'] != 'name':
                s['say'] = 'Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '?'
            elif confirmed:
                s['phase'] = 'dob'
                s['say'] = 'What is your date of birth?'
            elif asks >= 2:
