            else:
                s['say'] = 'Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '?'
        elif not handled and s['phase'] in ['dob', 'phone']:
            if kind in ['refusal', 'purpose']:
                s['declines'] += 1
                if s['declines'] >= 2:
                    end('not_verified', 'declined')
