                        text = re.sub(r'\b' + word + r'\b', digit, text)
                    digits = re.sub(r'[\s,.-]', '', text)
                    if re.fullmatch(r'\d{4}', digits):
                        answer = digits
                    elif re.fullmatch(r'\d{1,3}', digits):
                        s['say'] = 'Please give me the remaining ' + str(4 - len(digits)) + ' digit' + ('s.' if len(digits) < 3 else '.')
                    else:
