                if answer:
                    s['verify_field'] = 'date_of_birth' if s['phase'] == 'dob' else 'phone_last4'
                    s['verify_answer'] = answer
                    s['phase'] = 'verifying'
                    s['buffer'] = ''
        elif not handled and s['phase'] == 'callback':
            if kind in ['refusal', 'nonanswer'] and not e['date_text'] and not e['time_text']:
                end('not_reached', 'no_callback')
            else:
                if e['date_text']:
                    s['callback_date'] = e['date_text']
                    s['callback_kind'] = e['date_kind']
                if e['time_text']:
