                d = parse_date(s['callback_date'], s.get('callback_kind', 'exact'), following(today))
                t = s['callback_time']
                day_bad = bool(s['callback_date']) and (d is None or d not in [today, following(today)])
                time_bad = bool(t) and not re.fullmatch(r'(?:1[0-8]:[0-5][0-9]|19:00)', t)
                past = False
