                    past = dt <= now
                if day_bad or time_bad or past:
                    s['invalid_callbacks'] += 1
                    s['callback_date'] = ''
                    s['callback_time'] = ''
                    if s['invalid_callbacks'] >= 2:
                        end('not_reached', 'no_callback')
                    else:
                        s['say'] = 'Please choose a later time today or on ' + spoken(following(today)) + ', between 10:00 and 19:00.'
                elif not d:
                    s['say'] = 'On which date can the customer be reached: today or ' + spoken(following(today)) + '?'
                elif not t:
                    s['say'] = 'At what time between 10:00 and 19:00 can the customer be reached?'
                else:
                    s['callback_request'] = dict(date=d.isoformat(), time=t)
                    s['action'] = 'schedule_callback'
                    s['phase'] = 'resolve'
        elif not handled and s['phase'] in ['collect', 'confirm', 'hardship']:
            if not s['verified'] or not s['loaded']:
                raise ValueError('account gate')
            if kind == 'change_recorded':
                prefix += 'A recorded promise cannot be changed or cancelled during this call. You can change it in the mobile app. '
                handled = True
            if not handled and (kind == 'hardship' or e['hardship_present'] == 'yes'):
